#include <iostream>

enum class LifeState { Alive, Down };
struct Character { int hp; };

LifeState stateOf(const Character& character) {
    if (character.hp > 0) return LifeState::Alive;
    return LifeState::Down;
}

int main() {
    Character player{};
    std::cin >> player.hp;
    const LifeState state{stateOf(player)};
    if (state == LifeState::Alive) std::cout << "alive\n";
    else std::cout << "down\n";
    return 0;
}

