#include <algorithm>
#include <iostream>

enum class Weapon { Sword, Magic };
struct Enemy { int hp; };

namespace battle {
int damageFor(Weapon weapon) {
    if (weapon == Weapon::Sword) return 5;
    return 12;
}
void attack(Enemy& enemy, Weapon weapon) {
    enemy.hp = std::max(0, enemy.hp - damageFor(weapon));
}
}

int main() {
    Enemy enemy{};
    int weaponCode{};
    std::cin >> enemy.hp >> weaponCode;
    const Weapon weapon{weaponCode == 1 ? Weapon::Sword : Weapon::Magic};
    battle::attack(enemy, weapon);
    std::cout << enemy.hp << '\n';
    return 0;
}

